const roleNames={EN:["Full recipe","Lighting","Composition","Palette","Materials","Motion","Style","Negative prompt"],HU:["Teljes recept","Világítás","Kompozíció","Színek","Anyagok","Mozgás","Stílus","Negatív prompt"],DE:["Ganzes Rezept","Licht","Komposition","Palette","Materialien","Bewegung","Stil","Negativer Prompt"],FR:["Recette complète","Lumière","Composition","Palette","Matières","Mouvement","Style","Prompt négatif"],ES:["Receta completa","Iluminación","Composición","Paleta","Materiales","Movimiento","Estilo","Prompt negativo"],IT:["Ricetta completa","Luce","Composizione","Tavolozza","Materiali","Movimento","Stile","Prompt negativo"],PT:["Receita completa","Luz","Composição","Paleta","Materiais","Movimento","Estilo","Prompt negativo"],PL:["Cały przepis","Światło","Kompozycja","Paleta","Materiały","Ruch","Styl","Prompt negatywny"]};
export function creativeRecipeLabels(language="EN"){
  const values=dictionaries[language]||dictionaries.EN;
  return Object.fromEntries(keys.map((key,index)=>[key,values[index]||dictionaries.EN[index]]));
}
const element=(tag,content="",className="")=>{const node=document.createElement(tag);if(content)node.textContent=content;if(className)node.className=className;return node;};
const button=(label,handler)=>{const node=element("button",label);node.type="button";node.addEventListener("click",handler);return node;};
function field(root,name,kind="input"){
  const label=element("label"),span=element("span");span.dataset.crText=name;label.append(span);
  const input=element(kind);input.dataset.crField=name;if(kind==="textarea")input.rows=3;label.append(input);root.append(label);return input;
}
function download(name,value){const url=URL.createObjectURL(new Blob([value],{type:"application/json"}));const a=element("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

export function attachCreativeRecipes({getLanguage,getCurrent,restore,buildPassport}={}){
  const t=()=>creativeRecipeLabels(getLanguage?.()||"EN");
  const roles=()=>roleNames[getLanguage?.()]||roleNames.EN;
  let storage;try{storage=localStorage;}catch{storage={getItem(){throw Error("storage");}};}
  const store=createCreativeRecipeStore(storage),selected=new Map();
  let transient=null,capture=null,lastPlan=null,lastRoute="same";
  const root=element("details","","creative-recipes panel");root.id="creative-recipes";
  const summary=element("summary");summary.dataset.crText="title";root.append(summary);
  const intro=element("p");intro.dataset.crText="intro";root.append(intro);
  const actions=element("div","","cr-actions"),status=element("p","","cr-status");status.setAttribute("role","status");
  const add=button("",()=>openCapture({...getCurrent(),filename:t().fromEditor,kind:["video","i2v"].includes(getCurrent().mode)?"video":"image"}));add.dataset.crText="fromEditor";
  const backup=button("",()=>download("Prompt_Studio_Proven_Recipes.json",store.export()));backup.dataset.crText="export";
  const importFile=element("input");importFile.type="file";importFile.accept=".json,application/json";importFile.hidden=true;
  const importButton=button("",()=>importFile.click());importButton.dataset.crText="import";
  backup.disabled=Boolean(store.problem());importButton.disabled=Boolean(store.problem());
  actions.append(add,backup,importButton,importFile);root.append(actions);
  const privateNote=element("p","","cr-help");privateNote.dataset.crText="private";root.append(privateNote);
  const query=field(root,"search");query.type="search";query.maxLength=150;
  const list=element("div","","cr-list");root.append(list);
  const builder=element("div","","cr-builder");
  const route=element("select");route.dataset.crField="route";builder.append(route);
  const scene=field(builder,"scene","textarea"),change=field(builder,"change"),motion=field(builder,"motion","textarea");
  const make=button("",()=>build());make.dataset.crText="build";builder.append(make);
  const prompt=field(builder,"draft","textarea");prompt.rows=8;
  const negative=field(builder,"negative","textarea");
  const outgoing=element("div","","cr-actions");
  const composed=()=>creativePromptFor("recipes",prompt.value,lastPlan?.language||"EN");
  const mixSection=()=>creativeMixSectionFor("recipes",lastPlan?.language||"EN");
  const outputOrigins=()=>[...(lastPlan?.provenance||[]).filter(x=>!mixSection()||x.role!=="style-mix"),...(mixSection()?[{role:"style-mix",title:mixSection(),sourceId:"",filename:"",model:""}]:[])];
  const copy=button("",()=>copyText(composed()));copy.dataset.crText="copy";
  const use=button("",()=>{if(!prompt.value.trim())return;if(getCurrent()?.prompt?.trim()&&!confirm(t().overwrite))return;
    restore({mode:lastRoute==="video"?"i2v":lastPlan?.kind==="video"?"video":"image",prompt:composed(),scenePrompt:prompt.value,mixDirection:mixSection(),negative:negative.value,origins:outputOrigins(),language:lastPlan?.language||getCurrent()?.language||"EN"});});use.dataset.crText="use";
  const workbench=button("",()=>{if(prompt.value.trim())document.dispatchEvent(new CustomEvent("prompt-studio-workbench-load",{detail:{prompt:composed(),scenePrompt:prompt.value,mixDirection:mixSection(),negative:negative.value,origins:outputOrigins()},cancelable:true}));});workbench.dataset.crText="workbench";
  const ai=button("",()=>{if(prompt.value.trim())document.dispatchEvent(new CustomEvent("prompt-studio-ask-ai",{detail:{text:composed()+(negative.value.trim()?"\n\nNegative prompt: "+negative.value:"")+(lastPlan?.notes.length?"\n\nUser observations to consider (do not copy explanations into the prompt):\n"+JSON.stringify(lastPlan.notes):""),task:"improve"}}));});ai.dataset.crText="ai";
  const copyNegative=button("",()=>copyText(negative.value));copyNegative.dataset.crText="negative";
  const saveDraft=button("",()=>openCapture({filename:t().draft,prompt:composed(),scenePrompt:prompt.value,mixDirection:mixSection(),negative:negative.value,kind:lastPlan?.kind||"image",origins:outputOrigins(),language:lastPlan?.language||getCurrent()?.language||"EN"}));saveDraft.dataset.crText="save";
  outgoing.append(copy,copyNegative,use,workbench,ai,saveDraft);builder.append(outgoing);prompt.id="creative-recipe-draft";
  const provenance=element("div","","cr-provenance"),experience=element("div","","cr-experience"),recorded=element("details");
  const recordedTitle=element("summary");recordedTitle.dataset.crText="settings";const settings=element("pre");recorded.append(recordedTitle,settings);
  builder.append(provenance,experience,recorded);root.append(builder,status);
  const place=document.getElementById("prompt-workbench")||document.querySelector(".result-column");if(!place)return null;place.after(root);
  const dialog=element("dialog","","creative-recipe-dialog");dialog.setAttribute("aria-label",t().save);document.body.append(dialog);
  const dialogTitle=element("h2");dialogTitle.dataset.crText="save";dialog.append(dialogTitle);
  const title=field(dialog,"name");title.maxLength=120;
  const role=field(dialog,"role","select");
  const original=field(dialog,"sourcePrompt","textarea");original.readOnly=true;original.rows=5;
  const take=button("",()=>{const value=original.value.slice(original.selectionStart,original.selectionEnd).trim();if(value)excerpt.value=value;else feedback.textContent=t().needFragment;});take.dataset.crText="takeSelection";dialog.append(take);
  const excerpt=field(dialog,"fragment","textarea"),worked=field(dialog,"worked","textarea"),avoid=field(dialog,"avoid","textarea");
  worked.maxLength=2000;avoid.maxLength=2000;excerpt.maxLength=50000;
  role.addEventListener("change",()=>{original.value=role.value==="negative"?capture?.recipe.negative||"":capture?.recipe.prompt||"";if(role.value==="negative"&&!excerpt.value.trim())excerpt.value=capture?.recipe.negative||"";});
  const feedback=element("p","","cr-status");feedback.setAttribute("role","status");dialog.append(feedback);
  const save=button("",()=>{
    if(!capture||!title.value.trim()){feedback.textContent=t().name;return;}
    if(role.value!=="recipe"&&!excerpt.value.trim()){feedback.textContent=t().needFragment;return;}
    try{const entry=store.save({...capture,title:title.value,role:role.value,excerpt:excerpt.value,worked:worked.value,avoid:avoid.value});
      if(transient?.source.id&&transient.source.id===entry.source.id){selected.delete(transient.id);transient=null;}
      if(selected.has(entry.id)||selected.size<8)selected.set(entry.id,entry.role);dialog.close();status.textContent=t().stored;render();
      document.dispatchEvent(new CustomEvent("prompt-studio-creative-saved",{detail:{sourceId:entry.source.id,message:t().stored}}));
    }catch(error){feedback.textContent=error.message==="limit"?t().limit:t().failed;}
  });save.dataset.crText="save";dialog.append(save,button("×",()=>dialog.close()));
  const surpriseLabel=element("label","","cr-check"),surpriseCheck=element("input");surpriseCheck.type="checkbox";const surpriseSpan=element("span");surpriseSpan.dataset.crText="surpriseUse";surpriseLabel.append(surpriseCheck,surpriseSpan);root.insertBefore(surpriseLabel,builder);
  function sourceItem(entry){return {id:entry.source.id,filename:entry.source.filename,kind:entry.source.kind,model:entry.source.model,prompt:entry.recipe.prompt,scenePrompt:entry.recipe.scenePrompt,mixDirection:entry.recipe.mixDirection,negative:entry.recipe.negative,language:entry.recipe.language,settings:entry.recipe.settings,origins:entry.origins};}
  function openCapture(item,existing=null){
    capture=existing||snapshotCreativeRecipe(item);if(!capture)return;
    title.value=capture.title;role.value=capture.role;original.value=capture.recipe.prompt;excerpt.value=capture.excerpt;worked.value=capture.worked;avoid.value=capture.avoid;feedback.textContent=store.problem()?t().storage:"";
    save.disabled=Boolean(store.problem());dialog.showModal();title.focus();
  }
  function entries(){return [...store.list(),...(transient?[transient]:[])];}
  function selections(){const all=entries();return [...selected].map(([entryId,role])=>({entry:all.find(x=>x.id===entryId),role})).filter(x=>x.entry);}
  function fillRoles(select,value){select.replaceChildren(...creativeRoles.map((key,index)=>new Option(roles()[index],key)));select.value=value;}
  function render(){
    list.replaceChildren();const needle=query.value.trim().toLocaleLowerCase();
    const visible=entries().filter(x=>!needle||[x.title,x.worked,x.avoid,x.excerpt,x.source.filename].join(" ").toLocaleLowerCase().includes(needle));
    if(!visible.length)list.append(element("p",t().empty));
    for(const entry of visible){
      const row=element("article","","cr-card"),top=element("div","","cr-actions"),check=element("input");check.type="checkbox";check.checked=selected.has(entry.id);check.setAttribute("aria-label",entry.title);
      check.addEventListener("change",()=>{if(check.checked){if(selected.size>=8){check.checked=false;status.textContent="8 / 8";return;}selected.set(entry.id,as.value);}else selected.delete(entry.id);});
      const label=element("label","","cr-check");label.append(check,element("strong",entry.title));top.append(label);
      const as=element("select");fillRoles(as,selected.get(entry.id)||entry.role);as.setAttribute("aria-label",t().role+": "+entry.title);
      as.addEventListener("change",()=>{if(selected.has(entry.id))selected.set(entry.id,as.value);});top.append(as);
      top.append(button(t().edit,()=>openCapture(sourceItem(entry),entry)));
      if(entry!==transient)top.append(button(t().remove,()=>{if(!confirm(t().removeConfirm))return;try{store.remove(entry.id);selected.delete(entry.id);render();}catch{status.textContent=t().failed;}}));
      const source=button(t().source,()=>document.dispatchEvent(new CustomEvent("prompt-studio-open-proven-source",{detail:{id:entry.source.id,report:()=>{status.textContent=t().missingSource;}}})));source.disabled=!entry.source.id;top.append(source);
      row.append(top,element("p",entry===transient?t().unsaved:(entry.source.filename||t().fromEditor),"cr-help"));
      if(entry.excerpt)row.append(element("p",entry.excerpt.slice(0,240)));
      if(entry.worked)row.append(element("p",t().worked+": "+entry.worked));
      if(entry.avoid)row.append(element("p",t().avoid+": "+entry.avoid,"cr-experience"));
      for(const origin of entry.origins){const line=element("p",t().origin+": "+origin.title+(origin.filename?" · "+origin.filename:""),"cr-help");if(origin.sourceId)line.append(button(t().source,()=>document.dispatchEvent(new CustomEvent("prompt-studio-open-proven-source",{detail:{id:origin.sourceId,report:()=>{status.textContent=t().missingSource;}}}))));row.append(line);}
      if(buildPassport){const passport=button(t().passport,()=>{const base=buildPassport(sourceItem(entry),getLanguage());copyText((base.text||base)+"\n\n"+creativePassportNotes(entry));});row.append(passport);}
      list.append(row);
    }
    if(store.problem())status.textContent=t().storage;
  }
  function build(){
    try{
      lastRoute=route.value;lastPlan=buildCreativePlan({route:lastRoute,scene:scene.value,change:change.value,motion:motion.value,selections:selections(),styleText:""});
      const parts=splitCreativePrompt(lastPlan.prompt),section=lastPlan.mixDirection??parts.direction;
      if((section||typeof lastPlan.mixDirection==="string")&&loadCreativeMixSection("recipes",section))prompt.value=parts.scene;else prompt.value=lastPlan.mixDirection?combineCreativePrompt(lastPlan.prompt,lastPlan.mixDirection):lastPlan.prompt;
      negative.value=lastPlan.negative;provenance.replaceChildren(element("h3",t().origin));experience.replaceChildren(element("h3",t().notes));
      document.dispatchEvent(new Event("prompt-studio-draft-updated"));
      for(const source of lastPlan.provenance)provenance.append(element("p",(source.role==="style-mix"?t().mix:source.role==="reference"?t().reference:roles()[creativeRoles.indexOf(source.role)]||source.role)+": "+source.title+(source.filename?" · "+source.filename:"")+(source.model?" · "+source.model:"")));
      for(const note of lastPlan.notes){if(note.worked)experience.append(element("p",note.title+" — "+t().worked+": "+note.worked));if(note.avoid)experience.append(element("p",note.title+" — "+t().avoid+": "+note.avoid));}
      settings.textContent=JSON.stringify(lastPlan.settings,null,2);
      status.textContent=lastPlan.warnings.includes("attach-reference")?t().reference:t().settings;
      if(lastPlan.warnings.some(x=>x.startsWith("missing-fragment")))status.textContent+=" · "+t().needFragment;
    }catch(error){status.textContent=error.message==="selection"?t().needSelection:error.message==="scene"?t().needScene:error.message==="limit"?t().limit:t().needPrompt;}
  }
  async function copyText(value){try{await navigator.clipboard.writeText(value);status.textContent=t().copied;}catch{status.textContent=t().failed;}}
  query.addEventListener("input",render);
  route.addEventListener("change",()=>{scene.parentElement.hidden=route.value!=="new";change.parentElement.hidden=route.value!=="same";motion.parentElement.hidden=route.value!=="video";});
  importFile.addEventListener("change",async()=>{const file=importFile.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw Error("invalid");const count=store.import(await file.text());status.textContent=t().imported+": "+count;render();}catch{status.textContent=t().failed;}finally{importFile.value="";}});
  let mixText=()=>"";
  function translate(){
    for(const scope of [root,dialog])for(const node of scope.querySelectorAll("[data-cr-text]"))node.textContent=t()[node.dataset.crText];
    const current=route.value||"same";route.replaceChildren(...["same","new","video"].map(key=>new Option(t()[key],key)));route.value=current;
    fillRoles(role,role.value||"recipe");dialog.setAttribute("aria-label",t().save);route.setAttribute("aria-label",t().more);query.placeholder=t().search;
    route.dispatchEvent(new Event("change"));render();
  }
  document.getElementById("ui-language")?.addEventListener("change",translate);translate();
  const quick=button("★ "+t().title,()=>{root.open=true;root.scrollIntoView({behavior:"smooth",block:"start"});});
  quick.setAttribute("aria-label",t().title);quick.title=t().title;document.querySelector(".header-right")?.append(quick);
  const workbenchDraft=document.getElementById("workbench-draft");
  let workbenchPrompt="",workbenchOrigins=[];
  document.addEventListener("prompt-studio-workbench-load",event=>{if(!event.defaultPrevented&&workbenchDraft?.value===event.detail?.prompt){workbenchPrompt=event.detail.prompt;workbenchOrigins=event.detail.origins||[];}});
  if(workbenchDraft){const saveWorkbench=button(t().save,()=>openCapture({...getCurrent(),filename:t().workbench,prompt:creativePromptFor("workbench",workbenchDraft.value),negative:document.getElementById("workbench-negative")?.value||"",origins:workbenchDraft.value===workbenchPrompt?workbenchOrigins:[]}));workbenchDraft.parentElement.append(saveWorkbench);document.getElementById("ui-language")?.addEventListener("change",()=>{saveWorkbench.textContent=t().save;quick.textContent="★ "+t().title;quick.title=t().title;quick.setAttribute("aria-label",t().title);});}
  return {labels:t,openCapture,openTrialCapture(item,notes){openCapture(item);if(capture){title.value=notes.title;worked.value=notes.worked;avoid.value=notes.avoid;}},openRemix(item){transient=snapshotCreativeRecipe(item);if(!transient)return;selected.clear();selected.set(transient.id,"recipe");root.open=true;route.value="same";route.dispatchEvent(new Event("change"));render();build();root.scrollIntoView({behavior:"smooth",block:"start"});},
    setMixProvider(provider){mixText=provider;},
    enhanceSurprise(result){
      if(!surpriseCheck.checked)return result;
      const reusable=selections().filter(x=>x.role!=="recipe");if(!reusable.length){status.textContent=t().needFragment;return {...result,provenanceNotice:t().needFragment};}
      const plan=buildCreativePlan({route:"new",scene:result.prompt,selections:reusable});
      return {...result,prompt:plan.prompt,negative:[result.negative,plan.negative].filter(Boolean).join(", "),provenance:[...(result.provenance||[]),...plan.provenance]};
    }};
}

export function attachCreativeStyleMixers(options={}){
  return attachAdvancedStyleMixers({...options,getLabels:creativeRecipeLabels});
}
